div.script:
(function() {
    var form = document.getElementById('wizard-step0-form');
    if (!form) return;
    var radios = form.querySelectorAll('input.wizard-service-radio');
    var labels = form.querySelectorAll('label.wizard-service-card-label');
    var nextBtn = document.getElementById('wizard-step0-next');
    var hint = document.getElementById('wizard-step0-hint');
    function updateSelection() {
        var anyChecked = false;
        labels.forEach(function(l) {
            var card = l.querySelector('.wink-card-selectable');
            if (!card) return;
            var r = l.querySelector('input[type="radio"]');
            if (r && r.checked) { card.classList.add('wink-card-selected'); anyChecked = true; }
            else card.classList.remove('wink-card-selected');
        });
        if (nextBtn) nextBtn.disabled = !anyChecked;
        if (hint) hint.style.display = anyChecked ? 'none' : '';
    }
    radios.forEach(function(r) { r.addEventListener('change', updateSelection); });
    updateSelection();
})();

t.script:
(function() {
    var cb = document.getElementById('review-confirm-check');
    var btn = document.getElementById('review-submit-btn');
    if (!cb || !btn) return;
    cb.addEventListener('change', function() { btn.disabled = !cb.checked; });
})();

(function() {
    var form = document.getElementById('wizard-step2-employees-form');
    if (!form) return;
    var badge = document.getElementById('wizard-emp-count-badge');
    var cbs = form.querySelectorAll('input.wizard-emp-cb');
    var selectAll = document.getElementById('wizard-select-all');
    var deselectAll = document.getElementById('wizard-deselect-all');
    function updateCount() {
        var n = 0;
        cbs.forEach(function(cb) { if (cb.checked) n++; });
        if (badge) badge.textContent = n + ' selected';
    }
    cbs.forEach(function(cb) { cb.addEventListener('change', updateCount); });
    if (selectAll) selectAll.addEventListener('click', function(e) {
        e.preventDefault();
        cbs.forEach(function(cb) { cb.checked = true; });
        updateCount();
    });
    if (deselectAll) deselectAll.addEventListener('click', function(e) {
        e.preventDefault();
        cbs.forEach(function(cb) { cb.checked = false; });
        updateCount();
    });
    updateCount();
})();

div.script:
(function() {
    var matrix = ;
    var cycles = ;

    // Utility to find specific cycle ids
    var monthlyCycle = ;
    var annualCycle = ;

    var toggle = document.getElementById('wink-billing-cycle-toggle');
    var recurrenceInput = document.getElementById('wink-hidden-recurrence-id');
    var pricingInput = document.getElementById('wink-selected-pricing-id');
    var labelMonthly = document.getElementById('label-monthly');
    var labelAnnual = document.getElementById('label-annual');

    function updateAll() {
        var isAnnual = toggle.checked;
        var activeCycle = isAnnual ? (annualCycle || monthlyCycle) : monthlyCycle;
        var activeCycleId = activeCycle.recurrence_id_str;

        recurrenceInput.value = activeCycleId;
        labelMonthly.classList.toggle('active', !isAnnual);
        labelAnnual.classList.toggle('active', isAnnual);

        document.querySelectorAll('.wink-tier-card-premium').forEach(function(card) {
            var variantId = card.dataset.variantId;
            var tierName = (card.dataset.tierName || '').toLowerCase().trim();
            var plan = matrix[activeCycleId + '|' + variantId] || matrix[activeCycleId + '|' + tierName];

            if (!plan) {
                // Robust fallback for attribute matching
                for (var key in matrix) {
                    if (key.startsWith(activeCycleId + '|')) {
                        var p = matrix[key];
                        var attrs = (p.variant_attribute_names || []).map(a => a.toLowerCase().trim());
                        if (attrs.includes(tierName)) { plan = p; break; }
                    }
                }
            }

            var amountEl = card.querySelector('.wink-tier-amount');
            var cycleEl = card.querySelector('.wink-cycle-label');
            if (plan) {
                var symbol = plan.currency_symbol || 'AED';
                amountEl.textContent = symbol + ' ' + Number(plan.price).toLocaleString('en-US', {minimumFractionDigits:2});
                if (cycleEl) cycleEl.textContent = isAnnual ? 'annually' : 'monthly';
                card.dataset.pricingId = plan.pricing_id;
            } else {
                amountEl.textContent = '—';
                card.dataset.pricingId = '';
            }

            // Disable Subscribe when no pricing for current cycle
            var subBtn = card.querySelector('.wink-subscribe-btn');
            if (subBtn) {
                subBtn.disabled = !plan;
                subBtn.style.opacity = plan ? '1' : '0.4';
            }

            // If this card is selected, update the hidden pricing input
             if (card.classList.contains('selected') && plan) {
                pricingInput.value = plan.pricing_id;
            }
        });

    }

    toggle.addEventListener('change', updateAll);
    labelMonthly.addEventListener('click', function() { toggle.checked = false; updateAll(); });
    labelAnnual.addEventListener('click', function() { toggle.checked = true; updateAll(); });

    // Subscribe buttons: set pricing hidden input before native submit.
    // The button itself carries name="tier_id" value="{id}" so tier is
    // automatically included in the POST by the browser.
    document.querySelectorAll('.wink-subscribe-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
            var card = btn.closest('.wink-tier-card-premium');
            if (!card) return;

            // Set pricing from this card's current billing cycle
            if (card.dataset.pricingId) {
                pricingInput.value = card.dataset.pricingId;
            }

            // Ensure next_step is set to advance wizard
            var form = btn.closest('form');
            if (form) {
                var nextStepInput = form.querySelector('input[name="next_step"]');
                if (nextStepInput) nextStepInput.value = '2';
            }
            // Let native type="submit" handle form submission
        });
    });

    // Card click just highlights (visual selection), doesn't submit
    document.querySelectorAll('.wink-tier-card-premium').forEach(function(card) {
        card.addEventListener('click', function(e) {
            // Don't trigger on Subscribe button clicks
            if (e.target.closest('.wink-subscribe-btn')) return;

            document.querySelectorAll('.wink-tier-card-premium').forEach(function(c) { c.classList.remove('selected'); });
            card.classList.add('selected');

            // Update hidden pricing input on card click
            if (card.dataset.pricingId) {
                pricingInput.value = card.dataset.pricingId;
            }

            updateAll();
        });
    });

    // Initial load
    setTimeout(updateAll, 100);

    // UI-REV-001: Compare Plans toggle
    var compareBtn = document.getElementById('wink-compare-btn');
    var compareTable = document.getElementById('wink-compare-table');
    if (compareBtn && compareTable) {
        compareBtn.addEventListener('click', function(e) {
            e.preventDefault();
            var hidden = compareTable.classList.toggle('d-none');
            compareBtn.classList.toggle('open', !hidden);
            compareBtn.querySelector('i').style.transform = hidden ? '' : 'rotate(180deg)';
        });
    }

    // Point 6: Show all features logic
    document.querySelectorAll('.wink-show-all-features').forEach(function(link) {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            var tierId = link.dataset.tierId;
            var container = document.getElementById('features_' + tierId);
            container.querySelectorAll('.tiered-feature').forEach(function(item) {
                item.classList.remove('d-none');
            });
            link.parentElement.remove();
        });
    });
})();

(function() {
    var radios = document.querySelectorAll('input.wink-tier-radio');
    var sections = document.querySelectorAll('.tier-employees-section');
    function updateVisibility() {
        var selected = document.querySelector('input.wink-tier-radio:checked');
        var tierId = selected ? selected.value : '';
        sections.forEach(function(section) {
            section.style.display = (section.id === 'tier_employees_' + tierId) ? 'block' : 'none';
        });
    }
    if (radios.length) radios.forEach(function(radio) { radio.addEventListener('change', updateVisibility); });
    updateVisibility();
})();

t.script:
(function() {
    var form = document.querySelector('form[action="/my/requests/submit"]');
    if (!form) return;
    form.addEventListener('click', function(e) {
        var target = e.target;
        if (target.classList.contains('wink-select-all-employees')) {
            e.preventDefault();
            form.querySelectorAll('input[name="employee_ids"]').forEach(function(cb) { cb.checked = true; });
        } else if (target.classList.contains('wink-deselect-all-employees')) {
            e.preventDefault();
            form.querySelectorAll('input[name="employee_ids"]').forEach(function(cb) { cb.checked = false; });
        } else if (target.classList.contains('wink-bundle-select-all')) {
            e.preventDefault();
            var block = target.closest('.bundle-item-employees');
            if (block) block.querySelectorAll('.form-check-input').forEach(function(cb) { cb.checked = true; });
        } else if (target.classList.contains('wink-bundle-deselect-all')) {
            e.preventDefault();
            var block = target.closest('.bundle-item-employees');
            if (block) block.querySelectorAll('.form-check-input').forEach(function(cb) { cb.checked = false; });
        }
    });
})();

(function() {
    // ── Reactive Activate button ──────────────────────────
    function updateActivateBtn(modal) {
        var btn  = modal.querySelector('.wink-activate-submit');
        var hint = modal.querySelector('.wink-activate-hint');
        if (!btn) return;
        var docsOk = btn.getAttribute('data-docs-ok') === '1';
        var reqEmp = btn.getAttribute('data-req-emp') === '1';
        if (!docsOk) {
            btn.disabled = true;
            if (hint) hint.classList.add('d-none');
            return;
        }
        var empSelected = modal.querySelectorAll('.wink-emp-checkbox:checked').length > 0;
        if (reqEmp && !empSelected) {
            btn.disabled = true;
            if (hint) hint.classList.remove('d-none');
        } else {
            btn.disabled = false;
            if (hint) hint.classList.add('d-none');
        }
    }

    document.querySelectorAll('.modal[id^="wink-activate-modal-"]').forEach(function(m) {
        m.addEventListener('shown.bs.modal', function() { updateActivateBtn(m); });
        updateActivateBtn(m);
    });

    // ── Employee card toggle ──────────────────────────────
    document.querySelectorAll('.wink-emp-card').forEach(function(card) {
        var cb = card.querySelector('.wink-emp-checkbox');
        if (!cb) return;
        card.addEventListener('click', function() {
            cb.checked = !cb.checked;
            card.classList.toggle('selected', cb.checked);
            var modal = card.closest('.modal');
            syncEmployeesToForm(modal);
            if (modal) updateActivateBtn(modal);
        });
    });

    function syncEmployeesToForm(modal) {
        if (!modal) return;
        var form = modal.querySelector('.wink-activate-form');
        if (!form) return;
        form.querySelectorAll('input[name="employee_ids"]').forEach(function(el) { el.remove(); });
        // Add one hidden input per checked employee
        modal.querySelectorAll('.wink-emp-checkbox:checked').forEach(function(checked) {
            var hidden = document.createElement('input');
            hidden.type = 'hidden';
            hidden.name = 'employee_ids';
            hidden.value = checked.value;
            form.appendChild(hidden);
        });
    }

    // ── Re-upload toggle ──────────────────────────────────
    document.querySelectorAll('.wink-reupload-toggle').forEach(function(link) {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            var panel = document.querySelector(link.getAttribute('data-target'));
            if (!panel) return;
            panel.classList.toggle('d-none');
            var icon = link.querySelector('i');
            if (icon) icon.className = panel.classList.contains('d-none')
                ? 'fa fa-refresh me-1' : 'fa fa-chevron-up me-1';
        });
    });

    // ── Auto-open modal after doc upload redirect ─────────
    var params = new URLSearchParams(window.location.search);
    var openModalId = params.get('open_modal');
    if (openModalId && typeof bootstrap !== 'undefined') {
        var modalEl = document.getElementById('wink-activate-modal-' + openModalId);
        if (modalEl) {
            var bsModal = new bootstrap.Modal(modalEl);
            modalEl.addEventListener('shown.bs.modal', function() {
                updateActivateBtn(modalEl);
            }, { once: true });
            bsModal.show();
        }
    }
})();

div.script:
(function() {
    function updateActivateBtn(modal) {
        var btn  = modal.querySelector('.wink-activate-submit');
        var hint = modal.querySelector('.wink-activate-hint');
        if (!btn) return;
        var docsOk = btn.getAttribute('data-docs-ok') === '1';
        var reqEmp = btn.getAttribute('data-req-emp') === '1';
        if (!docsOk) {
            btn.disabled = true;
            if (hint) hint.classList.add('d-none');
            return;
        }
        var empSelected = modal.querySelectorAll('.wink-emp-checkbox:checked').length > 0;
        if (reqEmp && !empSelected) {
            btn.disabled = true;
            if (hint) hint.classList.remove('d-none');
        } else {
            btn.disabled = false;
            if (hint) hint.classList.add('d-none');
        }
    }

    document.querySelectorAll('.modal[id^="wink-bnd-modal-"]').forEach(function(m) {
        m.addEventListener('shown.bs.modal', function() { updateActivateBtn(m); });
        updateActivateBtn(m);
    });

    document.querySelectorAll('.wink-emp-card').forEach(function(card) {
        var cb = card.querySelector('.wink-emp-checkbox');
        if (!cb) return;
        card.addEventListener('click', function() {
            cb.checked = !cb.checked;
            card.classList.toggle('selected', cb.checked);
            var modal = card.closest('.modal');
            if (modal) {
                syncEmployeesToForm(modal);
                updateActivateBtn(modal);
            }
        });
    });

    function syncEmployeesToForm(modal) {
        if (!modal) return;
        var form = modal.querySelector('.wink-activate-form');
        if (!form) return;
        form.querySelectorAll('input[name="employee_ids"]').forEach(function(el) { el.remove(); });
        modal.querySelectorAll('.wink-emp-checkbox:checked').forEach(function(checked) {
            var hidden = document.createElement('input');
            hidden.type = 'hidden';
            hidden.name = 'employee_ids';
            hidden.value = checked.value;
            form.appendChild(hidden);
        });
    }

    document.querySelectorAll('.wink-reupload-toggle').forEach(function(link) {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            var panel = document.querySelector(link.getAttribute('data-target'));
            if (!panel) return;
            panel.classList.toggle('d-none');
            var icon = link.querySelector('i');
            if (icon) icon.className = panel.classList.contains('d-none')
                ? 'fa fa-refresh me-1' : 'fa fa-chevron-up me-1';
        });
    });

    // Auto-open after doc upload redirect
    var params = new URLSearchParams(window.location.search);
    var openModalId = params.get('open_modal');
    if (openModalId && typeof bootstrap !== 'undefined') {
        var modalEl = document.getElementById('wink-bnd-modal-' + openModalId);
        if (modalEl) {
            var bsModal = new bootstrap.Modal(modalEl);
            modalEl.addEventListener('shown.bs.modal', function() {
                updateActivateBtn(modalEl);
            }, { once: true });
            bsModal.show();
        }
    }
})();
